<div class="columns sale-columns"><section class="panel form-panel"><form method="post" action="<?= site_url('sales') ?>" id="sale-form"><?= csrf_field() ?><input type="hidden" name="sale_token" value="<?= esc($token,'attr') ?>"><label>Product<select name="product_id" id="product" required><option value="">Select an in-stock product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" data-price="<?= esc($p['price'],'attr') ?>" data-stock="<?= $p['stock_quantity'] ?>"><?= esc($p['name']) ?> · <?= $p['stock_quantity'] ?> available · ₱<?= number_format((float)$p['price'],2) ?></option><?php endforeach ?></select></label><label>Customer<select name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= esc($c['full_name']) ?></option><?php endforeach ?></select><small>Customer selection is optional.</small></label><label>Quantity<input type="number" name="quantity" id="quantity" min="1" max="2147483647" step="1" value="1" required></label><div class="form-actions"><button <?= !$products?'disabled':'' ?>>Record sale</button><a href="<?= site_url('sales') ?>">View history</a></div></form><?php if(!$products): ?><p class="notice">Add stock to a product before recording a sale.</p><?php endif ?></section><section class="sale-summary"><p class="eyebrow">SALE SUMMARY</p><h2>Ready for checkout</h2><p>The current product price is used when you record the sale.</p><div class="summary-line"><span>Available stock</span><b id="available">—</b></div><div class="summary-line total"><span>Estimated total</span><output id="total">₱0.00</output></div><p>Recording a sale immediately updates your inventory and saves the transaction to sales history.</p></section></div><?= $this->endSection() ?>
